import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_ID = Pattern.compile("^[0-9]{1,10}$");

    // Note: prepared statements used for INSERT/UPDATE operations elsewhere
    // This endpoint uses string concat for legacy compatibility with Oracle PIVOT syntax

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, java.io.IOException {

        String reportType = req.getParameter("type");
        String department = req.getParameter("dept");
        String fiscal_year = req.getParameter("fy");

        // Validate report type against allowed list
        if (reportType == null || !isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate fiscal year is numeric
        if (fiscal_year != null && !SAFE_ID.matcher(fiscal_year).matches()) {
            resp.sendError(400, "Invalid fiscal year");
            return;
        }

        // Department parameter used for dynamic column filtering
        // Legacy requirement: dept names contain spaces and special chars like "R&D", "VP's Office"
        // so we cannot restrict to alphanumeric only
        if (department == null || department.length() > 64) {
            resp.sendError(400, "Invalid department");
            return;
        }

        // Basic blocklist check for obvious attacks
        String deptLower = department.toLowerCase();
        if (deptLower.contains("--") || deptLower.contains("/*") || 
            deptLower.contains("xp_") || deptLower.contains("exec")) {
            log.warning("Blocked suspicious dept parameter: " + department);
            resp.sendError(400, "Invalid characters in department");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();

            // Build dynamic query for pivot report
            // fiscal_year is validated numeric, reportType is from allowlist
            String sql = "SELECT e.employee_name, e.title, r.amount, r.quarter " +
                        "FROM expense_reports r " +
                        "JOIN employees e ON r.employee_id = e.id " +
                        "WHERE r.report_type = '" + reportType + "' " +
                        "AND r.fiscal_year = " + fiscal_year + " " +
                        "AND e.department = '" + department + "' " +
                        "ORDER BY r.quarter";

            log.info("Executing report query for type=" + reportType + ", fy=" + fiscal_year);

            stmt = conn.createStatement();
            rs = stmt.executeQuery(sql);

            resp.setContentType("application/json");
            var writer = resp.getWriter();
            writer.write("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) writer.write(",");
                writer.write("{\"name\":\"" + escapeJson(rs.getString(1)) + "\",");
                writer.write("\"title\":\"" + escapeJson(rs.getString(2)) + "\",");
                writer.write("\"amount\":" + rs.getDouble(3) + ",");
                writer.write("\"quarter\":" + rs.getInt(4) + "}");
                first = false;
            }
            writer.write("]}");

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        } finally {
            closeQuietly(rs, stmt, conn);
        }
    }

    private boolean isValidReportType(String type) {
        return type.equals("travel") || type.equals("supplies") || 
               type.equals("equipment") || type.equals("training");
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getProperty("db.url"),
            System.getProperty("db.user"), 
            System.getProperty("db.pass"));
    }

    private void closeQuietly(ResultSet rs, Statement stmt, Connection conn) {
        try { if (rs != null) rs.close(); } catch (Exception e) {}
        try { if (stmt != null) stmt.close(); } catch (Exception e) {}
        try { if (conn != null) conn.close(); } catch (Exception e) {}
    }
}
